package main

import "fmt"

var data int

func main() {
	done := make(chan struct{})
	go func() {
		data = 42      // write happens-before the send (program order)
		close(done)    // close happens-before the receive returns
	}()
	<-done             // receive completes -> establishes the edge
	fmt.Println(data)  // guaranteed 42: write -> close -> receive -> read
}

