package solution

import "sync"

type Publisher struct {
	once    sync.Once   // guarantees compute runs exactly once
	compute func() int  // user-supplied work
	value   int         // cached result, published via once.Do
}

func New(compute func() int) *Publisher {
	return &Publisher{compute: compute}
}

func (p *Publisher) Get() int {
	// once.Do guarantees: the completion of this func happens-before
	// the return of EVERY Do call, so p.value is safely visible to all
	// concurrent callers with no further synchronization needed.
	p.once.Do(func() {
		p.value = p.compute()
	})
	return p.value
}

