package main

import (
	"fmt"
	"sync/atomic"
)

var result int
var done atomic.Bool // SC atomic (Go 1.19+) provides the ordering edge

func worker() {
	result = compute()  // write happens-before the atomic store (program order)
	done.Store(true)    // atomic store: synchronizes with a Load that sees it
}

func compute() int { return 99 }

func main() {
	go worker()
	for !done.Load() { // atomic load; once it sees true, the store happened-before it
	}
	fmt.Println(result) // guaranteed 99: result-write -> Store -> Load -> read
}

package solution

import "sync"

type Lazy[T any] struct {
	once sync.Once // ensures init runs exactly once
	val  T         // cached result, published via once.Do
}

// Value runs init at most once across all goroutines and returns the
// cached result. once.Do guarantees init's completion happens-before
// the return of every Value call, so val is safely visible to all.
func (l *Lazy[T]) Value(init func() T) T {
	l.once.Do(func() {
		l.val = init()
	})
	return l.val
}
